// Authentic Comic Sans MS font binary data for Cloudflare Workers PDF generation
function base64ToUint8Array(base64) {
  if (typeof Buffer !== 'undefined') {
    return new Uint8Array(Buffer.from(base64, 'base64'));
  }
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export const COMIC_SANS_REGULAR_BASE64 = "";
export const COMIC_SANS_BOLD_BASE64 = "";

let cachedRegularBytes = null;
let cachedBoldBytes = null;

export function getComicSansRegularBytes() {
  if (!cachedRegularBytes) {
    cachedRegularBytes = base64ToUint8Array(COMIC_SANS_REGULAR_BASE64);
  }
  return cachedRegularBytes;
}

export function getComicSansBoldBytes() {
  if (!cachedBoldBytes) {
    cachedBoldBytes = base64ToUint8Array(COMIC_SANS_BOLD_BASE64);
  }
  return cachedBoldBytes;
}
